    10→export async function handleColumnSidecarUnavailability({
    11→  chain,
    12→  db,
    13→  metrics,
    14→  unavailableColumnIndices,
    15→  requestedColumns,
    16→  availableColumns,
    17→  slot,
    18→  blockRoot,
    19→}: {
    20→  chain: IBeaconChain;
    21→  db: IBeaconDb;
    22→  metrics: Metrics | null;
    23→  slot: Slot;
    24→  blockRoot?: Uint8Array;
    25→  unavailableColumnIndices: ColumnIndex[];
    26→  requestedColumns: ColumnIndex[];
    27→  availableColumns: ColumnIndex[];
    28→}): Promise<void> {
    29→  const logData: LogData = {
    30→    slot,
    31→    unavailableColumnIndices: prettyPrintIndices(unavailableColumnIndices),
    32→    requestedColumns: prettyPrintIndices(requestedColumns),
    33→    availableColumns: prettyPrintIndices(availableColumns),
    34→  };
    35→  if (blockRoot) {
    36→    logData.blockRoot = prettyBytes(blockRoot);
    37→  }
    38→
    39→  chain.logger.debug("dataColumnSidecar requested unavailable", logData);
    40→
    41→  const blockBytes = blockRoot ? await db.block.getBinary(blockRoot) : await db.blockArchive.getBinary(slot);
    42→  if (!blockBytes) {
    43→    chain.logger.verbose(
    44→      `Expected ${blockRoot ? "unfinalized" : "finalized"} block not found while handling unavailable dataColumnSidecar`,
    45→      {
    46→        slot,
    47→        blockRoot: blockRoot ? toRootHex(blockRoot) : "unknown",
    48→        earliestAvailableSlot: chain.earliestAvailableSlot,
    49→      }
    50→    );
    51→    return;
    52→  }
    53→
    54→  // Check for blob count in actual block
    55→  const blobsCount = getBlobKzgCommitmentsCountFromSignedBeaconBlockSerialized(chain.config, blockBytes);
    56→
    57→  // There are zero blobs for that column index, so we can safely return without any error
